<?php get_header(); ?><main id="primary" class="content-area"><div class="container"><header class="page-header"><h1><?php echo esc_html(is_search()?'Search Results':'Ntamba Journal'); ?></h1></header><?php if(have_posts()):while(have_posts()):the_post(); ?><article class="story-card" style="margin-bottom:1rem"><div class="section-kicker"><?php ntamba_posted_on(); ?></div><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php ntamba_thumbnail('medium_large'); ?><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),25)); ?></p></article><?php endwhile;the_posts_pagination();else: ?><div class="notice">No content found.</div><?php endif; ?></div></main><?php get_footer(); ?>